draw((-2,0)--(2,0));
draw((0,-2)--(0,2));
draw(A--C);

for (i = 0; i <= 7; ++i) {
  dot(sqrt(3)*dir(45*i));
  draw(sqrt(3)*dir(45*i)--sqrt(3)*dir(45*(i + 1)));
}

