draw((2-3/4,sqrt(3)/4)--(2-3/4,0),linewidth(0.8));
draw((3/4,0.1)--(3/4-0.1,0.1)--(3/4-0.1,0),linewidth(0.8));
draw((2-3/4,0.1)--(2-3/4+0.1,0.1)--(2-3/4+0.1,0),linewidth(0.8));
